    [2905]={name="Goat Fur Cloak",sourceType="quest_reward",instructions="Reward from the quest “The Perfect Stout” — pick it over the other choices. In Dun Morogh.",zone="Dun Morogh",questName="The Perfect Stout",lore="I'm on a quest, a quest to make the perfect stout. I know I can do it -- brewing's in my blood. I just need to find the right recipe... The Frostmane trolls grow a plant, shimmerweed, high up in the hills to the east."},
    [2908]={name="Thornblade",sourceType="quest_reward",instructions="Reward from the quest “A Dark Threat Looms” — pick it over the other choices. In Loch Modan.",zone="Loch Modan",questName="A Dark Threat Looms",lore="The keg fizzles slightly."},
