    [4109]={name="Excelsior Boots",sourceType="quest_reward",instructions="Reward from the quest “Excelsior”. In Stranglethorn Vale.",zone="Stranglethorn Vale",questName="Excelsior",lore="For this, I use only the best elder croc skins. They are more durable and a better canvas--if you will--for adding the designs and accents that make Drizzlik's Excelsior line."},
