    [7751]={name="Vorrel's Boots",sourceType="quest_reward",instructions="Reward from the quest “Vorrel's Revenge”. In Scarlet Monastery.",zone="Scarlet Monastery",questName="Vorrel's Revenge",lore="Even though my will is free, I can serve the Dark Lady no more. I feel my time on Azeroth has come to an end. My life force is shattered. Interrogator Vishas did this to me!"},
