    [9533]={name="Masons Fraternity Ring",sourceType="quest_reward",instructions="Reward from the quest “Divino-matic Rod” — pick it over the other choices. In Zul'Farrak.",zone="Zul'Farrak",questName="Divino-matic Rod",lore="Sergeant Bly stole from me! He said he'd only borrow it, but he stole my cherished divino-matic rod!! Without that rod how will I know where to dig new water holes??"},
    [9598]={name="Sleeping Robes",sourceType="quest_reward",instructions="Reward from the quest “Druid of the Claw” — pick it over the other choices. In Teldrassil.",zone="Teldrassil",questName="Druid of the Claw",lore="After examining this charm, I see now what must be done. Please take it, and do as I ask. You are to explore the deepest areas of the Ban'ethil Barrow Den."},
    [9601]={name="Cushioned Boots",sourceType="quest_reward",instructions="Reward from the quest “Sathrah's Sacrifice” — pick it over the other choices. In Darnassus.",zone="Darnassus",questName="Sathrah's Sacrifice",lore="Now you must finish the task to which you have been appointed. Take the spinnerets and offer Lady Sathrah's sacrifice to Elune; lay the great spider to rest."},
    [9624]={name="Triprunner Dungarees",sourceType="quest_reward",instructions="Reward from the quest “Rig Wars” — pick it over the other choices. In Gnomeregan.",zone="Gnomeregan",questName="Rig Wars",lore="Gnome technology - two years ago its most common use was as a punch line. Times certainly have changed. Now they've got a new rig built that's better than all our shredder models combined."},
    [9647]={name="Failed Flying Experiment",sourceType="quest_reward",instructions="Reward from the quest “Rescue OOX-22/FE!” — pick it over the other choices. In Feralas.",zone="Feralas",questName="Rescue OOX-22/FE!",lore="The gnome's voice crackles once again from the robot: \"I need to move OOX-22/FE to an open, safe place so it can begin a lengthy take-off procedure."},
