    [15822]={name="Shadowskin Spaulders",sourceType="quest_reward",instructions="Reward from the quest “Runecloth” — pick it over the other choices. In Timbermaw Hold.",zone="Timbermaw Hold",questName="Runecloth",lore="In Timbermaw, we are content. We do not like strangers. This is good for us, but it is bad for trade. Not long ago, a rare night elf friend came to Timbermaw and she wore a runecloth cloak."},
    [15825]={name="Traphook Jerkin",sourceType="quest_reward",instructions="Reward from the quest “Put Her Down” — pick it over the other choices. In Blackrock Spire.",zone="Blackrock Spire",questName="Put Her Down",lore="You have no doubt seen the worgs which the Blackrock orcs command. It is curious - no matter how many we destroy, their numbers never dwindle."},
