    [16659]={name="Deftkin Belt",sourceType="quest_reward",instructions="Reward from the quest “Je'neu of the Earthen Ring” — pick it over the other choices. In Ashenvale.",zone="Ashenvale",questName="Je'neu of the Earthen Ring",lore="The Earthen Ring is a shamanistic group dedicated to studying and preserving the elements. They have forgotten more about crazy old gods, ancient legends and lore than most scholars will ever know."},
