    [16823]={name="Nightslayer Shoulder Pads",sourceType="boss_drop",instructions="Drops from Sulfuron Harbinger in Molten Core.",zone="Molten Core",npc="Sulfuron Harbinger",lore="High priest of Ragnaros's flame, who keeps four healers at his back and lets them work."},
    [16886]={name="Outlaw Sabre",sourceType="quest_reward",instructions="Reward from the quest “Baron Aquanis” — pick it over the other choices. In Ashenvale.",zone="Ashenvale",questName="Baron Aquanis",lore="The defeated water elemental has left behind a strange water globe. You surmise that the object somehow fed the beast energy. Inside the globe, a putrid-looking form of water sloshes about."},
    [16905]={name="Bloodfang Chestpiece",sourceType="boss_drop",instructions="Drops from Nefarian.",npc="Nefarian",lore="Deathwing's son, working under Blackrock Mountain to breed the chromatic flight -- dragons carrying the blood of all five. He spent years in Stormwind's court as Lord Victor Nefarius while the work went on."},
    [16910]={name="Bloodfang Belt",sourceType="boss_drop",instructions="Drops from Vaelastrasz the Corrupt in Blackwing Lair.",zone="Blackwing Lair",npc="Vaelastrasz the Corrupt",lore="A red dragon of Alexstrasza's flight, broken by Nefarian's experiments. He asks to be killed before the corruption finishes taking him, and apologises while he fights."},
    [16911]={name="Bloodfang Bracers",sourceType="boss_drop",instructions="Drops from Razorgore the Untamed in Blackwing Lair.",zone="Blackwing Lair",npc="Razorgore the Untamed",lore="Set to guard the stolen dragon eggs. The raid takes control of the orb he is chained to and turns him on the clutch he was protecting."},
    [16977]={name="Warsong Boots",sourceType="quest_reward",instructions="Reward from the quest “Warsong Supplies” — pick it over the other choices. In Ashenvale.",zone="Ashenvale",questName="Warsong Supplies",lore="We are in short supply of a few items at the Warsong lumber camp!"},
    [17005]={name="Boorguard Tunic",sourceType="quest_reward",instructions="Reward from the quest “King of the Foulweald” — pick it over the other choices. In Ashenvale.",zone="Ashenvale",questName="King of the Foulweald",lore="another tribe of Furbolgs, the Foulweald, live southeast of Astranaar. They are not as many as the Thistlefur, but their ferocity poses a future threat."},
    [17054]={name="Joonho's Mercy",sourceType="world_drop",instructions="Drops from General Fangferror (rare spawn) in Kalimdor.",zone="Kalimdor",npc="General Fangferror",proc="Chance on hit: Blasts a target for 70 Arcane damage."},
    [17063]={name="Band of Accuria",sourceType="boss_drop",instructions="Drops from Ragnaros.",npc="Ragnaros",lore="The Firelord, one of the four Elemental Lords, bound to the Elemental Plane until the Dark Iron dwarves summoned him under Blackrock Mountain. The summoning cracked the mountain open and made the Molten Core."},
    [17069]={name="Striker's Mark",sourceType="boss_drop",instructions="Drops from Magmadar in Molten Core.",zone="Molten Core",npc="Magmadar",lore="A core hound of the deep fire, kept as a guard beast and fed by Ragnaros's lieutenants."},
    [17694]={name="Band of the Fist",sourceType="quest_reward",instructions="Reward from the quest “Allegiance to the Old Gods” — pick it over the other choices. In Blackfathom Deeps.",zone="Blackfathom Deeps",questName="Allegiance to the Old Gods",lore="This Twilight's Hammer follower cannot be allowed to complete his plan. The Twilight's Hammer do not understand the spirits of nature. They believe in the Old Gods--creatures of chaos and destruction that were long ago defeated."},
    [17705]={name="Thrash Blade",sourceType="quest_reward",instructions="Reward from the quest “Corruption of Earth and Seed” — pick it over the other choices. In Maraudon.",zone="Maraudon",questName="Corruption of Earth and Seed",lore="Deep in Maraudon lives an evil creature of chaos--Princess Theradras is an elemental force of earth related to the Old Gods. Ages ago, she and Zaetar, first son of Cenarius, began a relationship.",proc="Chance on hit: Grants an extra attack on your next swing."},
    [17710]={name="Charstone Dirk",sourceType="boss_drop",instructions="Drops from Princess Theradras in Maraudon.",zone="Maraudon",npc="Princess Theradras",lore="A princess of the earth elementals and the reason Maraudon is poisoned -- she holds the body of Zaetar, her demigod consort, at its heart."},
    [17713]={name="Blackstone Ring",sourceType="boss_drop",instructions="Drops from Princess Theradras in Maraudon.",zone="Maraudon",npc="Princess Theradras",lore="A princess of the earth elementals and the reason Maraudon is poisoned -- she holds the body of Zaetar, her demigod consort, at its heart."},
