    [17752]={name="Satyr's Lash",sourceType="boss_drop",instructions="Drops from Lord Vyletongue in Maraudon.",zone="Maraudon",npc="Lord Vyletongue",proc="Chance on hit: Sends a shadowy bolt at the enemy causing 55 to 85 Shadow damage."},
    [17772]={name="Zealous Shadowshard Pendant",sourceType="quest_reward",instructions="Reward from the quest “Shadowshard Fragments” — pick it over the other choices. In Maraudon.",zone="Maraudon",questName="Shadowshard Fragments",lore="The Desolace tribes of centaur protect that place wit' their lives, but they canna stop us from takin' what we need. You, you head to this Maraudon place and find the rock creatures made of shadowshard."},
    [17776]={name="Sprightring Helm",sourceType="quest_reward",instructions="Reward from the quest “Twisted Evils” — pick it over the other choices. In Maraudon.",zone="Maraudon",questName="Twisted Evils",lore="The crystal caverns of Terramok lie to the west, deep within Maraudon... It is an ancient place with much history. And I am looking to get my hands on some of it."},
    [17778]={name="Sagebrush Girdle",sourceType="quest_reward",instructions="Reward from the quest “Vyletongue Corruption” — pick it over the other choices. In Maraudon.",zone="Maraudon",questName="Vyletongue Corruption",lore="A satyr known as Vyletongue has corrupted the caverns of Maraudon, stunting the growth of many of the plants inside. Take this vial."},
    [17780]={name="Blade of Eternal Darkness",sourceType="boss_drop",instructions="Drops from Princess Theradras in Maraudon.",zone="Maraudon",npc="Princess Theradras",lore="A princess of the earth elementals and the reason Maraudon is poisoned -- she holds the body of Zaetar, her demigod consort, at its heart.",proc="Equip: Chance on landing a direct damage spell to deal 100 Shadow damage and restore 100 mana to you. (Proc chance: 10%)"},
