    [18823]={name="Aged Core Leather Gloves",sourceType="boss_drop",instructions="Drops from Garr in Molten Core.",zone="Molten Core",npc="Garr",lore="A lieutenant of Ragnaros who fights surrounded by his Firesworn, and grows stronger each time one of them falls."},
    [18957]={name="Brushwood Blade",sourceType="quest_reward",instructions="Reward from the quest “Druid of the Claw” — pick it over the other choices. In Teldrassil.",zone="Teldrassil",questName="Druid of the Claw",lore="After examining this charm, I see now what must be done. Please take it, and do as I ask. You are to explore the deepest areas of the Ban'ethil Barrow Den."},
    [19120]={name="Rune of the Guard Captain",sourceType="quest_reward",instructions="Reward from the quest “Job Opening: Guard Captain of Revantusk Village”. In The Hinterlands.",zone="The Hinterlands",questName="Job Opening: Guard Captain of Revantusk Village",lore="With the loss of Guard Captain Malkhor, the position of Guard Captain of Revantusk is once again open."},
    [19127]={name="Charred Leather Tunic",sourceType="quest_reward",instructions="Reward from the quest “WANTED: Overseer Maltorius” — pick it over the other choices. In Searing Gorge.",zone="Searing Gorge",questName="WANTED: Overseer Maltorius",lore="By order o' 'is eminence, Overseer Oilfist, the rogue Thorium Brotherhood agent an' newly hired commander o' the Dark Iron Slag Pit crew o' the Cauldron, Overseer Maltorius, is to be killed an' 'is head brung back as proof o' the deed."},
    [19159]={name="Woven Ivy Necklace",sourceType="quest_reward",instructions="Reward from the quest “Wanted: Vile Priestess Hexx and Her Minions” — pick it over the other choices. In The Hinterlands.",zone="The Hinterlands",questName="Wanted: Vile Priestess Hexx and Her Minions",lore="By order of Primal Torntusk, Vile Priestess Hexx and her minions are to be brought to justice! A grand reward is offered for any that slay the Vile Priestess Hexx and all of her Aman'zasi elite guard."},
    [19289]={name="Darkmoon Card: Maelstrom",sourceType="quest_reward",instructions="Reward from the quest “Darkmoon Elementals Deck”.",questName="Darkmoon Elementals Deck",lore="Now that you have gathered all of the Elemental cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.",proc="Equip: Chance to strike your melee target with lightning for 200 to 300 Nature damage."},
    [19352]={name="Chromatically Tempered Sword",sourceType="boss_drop",instructions="Drops from Chromaggus in Blackwing Lair.",zone="Blackwing Lair",npc="Chromaggus",lore="Nefarian's chromatic experiment, made into a sword. It carries the blood of every dragonflight and none of their loyalty."},
    [19377]={name="Prestor's Talisman of Connivery",sourceType="boss_drop",instructions="Drops from Nefarian.",npc="Nefarian",lore="Deathwing's son, working under Blackrock Mountain to breed the chromatic flight -- dragons carrying the blood of all five. He spent years in Stormwind's court as Lord Victor Nefarius while the work went on."},
    [19381]={name="Boots of the Shadow Flame",sourceType="boss_drop",instructions="Drops from Nefarian.",npc="Nefarian",lore="Deathwing's son, working under Blackrock Mountain to breed the chromatic flight -- dragons carrying the blood of all five. He spent years in Stormwind's court as Lord Victor Nefarius while the work went on."},
