    [20838]={name="Sunstrider Bow",sourceType="quest_reward",instructions="Reward from the quest “Felendren the Banished” — pick it over the other choices. In Sunstrider Isle.",zone="Sunstrider Isle",questName="Felendren the Banished",lore="A betrayer of our people resides atop Falthrien Academy to the southwest. Felendren is his name, and he was banished from blood elf lands for failing to heed the warnings of our teachers and elders."},
