    [21126]={name="Death's Sting",sourceType="boss_drop",instructions="Drops from C'Thun in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."},
    [21205]={name="Signet Ring of the Bronze Dragonflight",sourceType="quest_reward",instructions="Reward from the quest “The Qiraji Conqueror”. In Tanaris.",zone="Tanaris",questName="The Qiraji Conqueror"},
    [21278]={name="Stormshroud Gloves",sourceType="profession",instructions="Crafted with Leatherworking (requires skill 1).",profession="Leatherworking"},
    [21359]={name="Deathdealer's Boots",sourceType="quest_reward",instructions="Reward from the quest “Deathdealer's Boots”. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Deathdealer's Boots",lore="The most powerful qiraji wield items of such might, they'd give pause even to a dragon. Bring me the qiraji bindings of command and other minor components by and I'll create a set of powerful boots for you."},
    [21360]={name="Deathdealer's Helm",sourceType="quest_reward",instructions="Reward from the quest “Deathdealer's Helm”. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Deathdealer's Helm",lore="The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity. They mock me, knowing I cannot step further into their domain to save my brother Arygos."},
    [21361]={name="Deathdealer's Spaulders",sourceType="quest_reward",instructions="Reward from the quest “Deathdealer's Spaulders”. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Deathdealer's Spaulders",lore="It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon."},
    [21364]={name="Deathdealer's Vest",sourceType="quest_reward",instructions="Reward from the quest “Deathdealer's Vest”. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Deathdealer's Vest",lore="The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj. The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power."},
    [21406]={name="Cloak of Veiled Shadows",sourceType="quest_reward",instructions="Reward from the quest “Cloak of Veiled Shadows”. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Cloak of Veiled Shadows",lore="I'm glad to hear you're aiding us in our attack on Ahn'Qiraj. I can make you a protective item that'll be of assistance in the fight against our enemy."},
    [21459]={name="Crossbow of Imminent Doom",sourceType="boss_drop",instructions="Drops from Ossirian the Unscarred in Ruins of Ahn'Qiraj.",zone="Ruins of Ahn'Qiraj",npc="Ossirian the Unscarred",lore="A qiraji lieutenant holding the Ruins, whose name stopped being accurate the first time a raid used the crystals against him."},
    [21567]={name="Rune of Duty",sourceType="vendor",instructions="Bought from Illiyana Moonblaze in Mor'shan Base Camp — costs tokens or reputation.",zone="Mor'shan Base Camp",npc="Illiyana Moonblaze"},
    [21568]={name="Rune of Duty",sourceType="vendor",instructions="Bought from Illiyana Moonblaze in Mor'shan Base Camp — costs tokens or reputation.",zone="Mor'shan Base Camp",npc="Illiyana Moonblaze"},
    [21586]={name="Belt of Never-ending Agony",sourceType="boss_drop",instructions="Drops from C'Thun in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped."},
    [21602]={name="Qiraji Execution Bracers",sourceType="boss_drop",instructions="Drops from Emperor Vek'lor in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Emperor Vek'lor",lore="Twin emperor of the qiraji, and the one who inherited C'Thun's gift for magic instead of his brother's strength. Neither twin can be killed far from the other."},
    [21664]={name="Barbed Choker",sourceType="boss_drop",instructions="Drops from Fankriss the Unyielding in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Fankriss the Unyielding",lore="A vast qiraji burrower that spawns its young mid-fight and hurls intruders into the walls."},
    [21672]={name="Gloves of Enforcement",sourceType="boss_drop",instructions="Drops from Battleguard Sartura in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Battleguard Sartura",lore="The qiraji empire's finest soldier, who fights with her honour guard and refuses to be separated from them."},
    [21701]={name="Cloak of Concentrated Hatred",sourceType="boss_drop",instructions="Drops from The Prophet Skeram in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="The Prophet Skeram",lore="C'Thun's mouthpiece. Everything the qiraji believe, they believe because he told them the Old God said it."},
    [21710]={name="Cloak of the Fallen God",sourceType="quest_reward",instructions="Reward from the quest “The Savior of Kalimdor” — pick it over the other choices. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="The Savior of Kalimdor",lore="To the Caverns of Time you go, Lord:Lady;. Anachronos awaits your return. Give him the eye of C'Thun as he will undoubtedly wish to place it in his master's collection."},
    [21758]={name="Figurine - Black Pearl Panther",sourceType="profession",instructions="Crafted with Jewelcrafting (requires skill 1).",profession="Jewelcrafting",proc="Use: Increases attack power by 90 for 15 sec. (5 Min Cooldown)"},
    [21763]={name="Figurine - Truesilver Boar",sourceType="profession",instructions="Crafted with Jewelcrafting (requires skill 1).",profession="Jewelcrafting",proc="Use: Summons the Truesilver Boar to fight for you for 30 seconds. (15 Min Cooldown)"},
    [21767]={name="Simple Opal Ring",sourceType="profession",instructions="Crafted with Jewelcrafting (requires skill 1).",profession="Jewelcrafting"},
    [21809]={name="Fury of the Forgotten Swarm",sourceType="boss_drop",instructions="Drops from Colonel Zerran in Ruins of Ahn'Qiraj.",zone="Ruins of Ahn'Qiraj",npc="Colonel Zerran"},
    [21932]={name="Heavy Copper Ring",sourceType="profession",instructions="Crafted with Jewelcrafting (requires skill 1).",profession="Jewelcrafting"},
