    [22003]={name="Darkmantle Boots",sourceType="quest_reward",instructions="Reward from the quest “Anthion's Parting Words”. In Ironforge.",zone="Ironforge",questName="Anthion's Parting Words",lore="Valthalak's soul was stored in this amulet. In our greed we foolishly split it into three parts, not knowing the curse that would await us. The only way to stop Valthalak's spell is to put the medallion back together."},
    [22005]={name="Darkmantle Cap",sourceType="quest_reward",instructions="Reward from the quest “Saving the Best for Last”. In Ironforge.",zone="Ironforge",questName="Saving the Best for Last",lore="That's an amazing story! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut."},
    [22006]={name="Darkmantle Gloves",sourceType="quest_reward",instructions="Reward from the quest “Just Compensation”. In Ironforge.",zone="Ironforge",questName="Just Compensation",lore="I believe a reward is in order if I'm to keep you interested in saving my skin. Bring me the belt and set of gloves that you wish to upgrade."},
    [22009]={name="Darkmantle Tunic",sourceType="quest_reward",instructions="Reward from the quest “Saving the Best for Last”. In Ironforge.",zone="Ironforge",questName="Saving the Best for Last",lore="That's an amazing story! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut."},
    [22150]={name="Beads of Ogre Might",sourceType="quest_reward",instructions="Reward from the quest “Falrin's Vendetta” — pick it over the other choices. In Dire Maul.",zone="Dire Maul",questName="Falrin's Vendetta",lore="Yet I'm not one to give out favors freely, even if you were sent here by an old friend. I hold nothing but hatred and contempt for our brutish ogre neighbors."},
    [22241]={name="Dark Warder's Pauldrons",sourceType="boss_drop",instructions="Drops from Warder Stilgiss in Blackrock Depths.",zone="Blackrock Depths",npc="Warder Stilgiss"},
